"use strict";

// E01: the invocation is a CONSTRUCTION, not a call.
//
//     new bail();
//
// `bail` is an ordinary function declaration, so it HAS a [[Construct]]
// method and `new` really does enter its body -- which throws before
// construction can complete. That is the whole claim, and it is
// deliberately narrower than "`new` on a throwing thing aborts": `new` on
// an arrow, an `async` function or a generator also aborts the module, but
// with a `TypeError` raised on constructability BEFORE the body runs. That
// is a different proof, this rule does not perform it, and `valid.js`
// pins that those forms keep their authority here.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

// Constructable: a plain function declaration, neither async nor a
// generator.
function bail() {
  throw new Error("boom");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  new bail();
}

module.exports = safeOp;
